insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000011', '40000000-0000-4000-8000-000000000001', 'Leia a estrutura', 'A parte interna do cosseno é $x^2$, e sua derivada é $2x$, exatamente o fator que acompanha a função.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000001' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000012', '40000000-0000-4000-8000-000000000001', 'Defina a substituição', 'Escolha $u=x^2$. Então $du=2x\,dx$, de modo que todo o fator externo é absorvido.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000001' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000013', '40000000-0000-4000-8000-000000000001', 'Reescreva a integral', 'A integral passa a ser $\int\cos(u)\,du$. A variável $x$ não deve permanecer nesta linha.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000001' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000014', '40000000-0000-4000-8000-000000000001', 'Integre e retorne', 'Como $\int\cos(u)\,du=\sin(u)+C$, voltamos a $u=x^2$ e obtemos $\sin(x^2)+C$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000001' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000015', '40000000-0000-4000-8000-000000000001', 'Confira por derivação', 'A derivada de $\sin(x^2)$ é $\cos(x^2)\cdot2x$, que reproduz o integrando.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000001' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000021', '40000000-0000-4000-8000-000000000002', 'Reconheça a série', 'Cada termo é obtido multiplicando o anterior por $1/3$; portanto ela é geométrica.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000002' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000022', '40000000-0000-4000-8000-000000000002', 'Identifique os dados', 'O primeiro termo é $a=1$ porque a soma começa em $n=0$, e a razão é $r=1/3$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000002' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000023', '40000000-0000-4000-8000-000000000002', 'Verifique a condição', 'Como $|r|=1/3<1$, a série infinita converge e a fórmula da soma pode ser usada.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000002' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000024', '40000000-0000-4000-8000-000000000002', 'Calcule a soma', 'Aplicando $a/(1-r)$, temos $1/(1-1/3)=1/(2/3)=3/2$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000002' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000025', '40000000-0000-4000-8000-000000000002', 'Compare com a alternativa', 'A resposta correta deve afirmar simultaneamente a convergência e a soma $3/2$.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000002' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000031', '40000000-0000-4000-8000-000000000003', 'Organize a matriz', 'Para uma matriz $2\times2$ escrita como $\begin{pmatrix}a&b\\c&d\end{pmatrix}$, o determinante é $ad-bc$.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000003' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000032', '40000000-0000-4000-8000-000000000003', 'Identifique as entradas', 'Aqui, $a=2$, $b=1$, $c=3$ e $d=4$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000003' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000033', '40000000-0000-4000-8000-000000000003', 'Substitua na fórmula', 'Calculamos $ad-bc=2\cdot4-1\cdot3$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000003' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000034', '40000000-0000-4000-8000-000000000003', 'Efetue as operações', '$2\cdot4=8$ e $1\cdot3=3$; assim, $8-3=5$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000003' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000035', '40000000-0000-4000-8000-000000000003', 'Faça uma conferência', 'O resultado é um único número, não uma matriz; por isso a alternativa com $5$ é a compatível.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000003' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000041', '40000000-0000-4000-8000-000000000004', 'Escolha uma primitiva', 'Uma função cuja derivada é $3x^2$ é $x^3$.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000004' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000042', '40000000-0000-4000-8000-000000000004', 'Aplique a regra dos extremos', 'Para uma integral definida, use $[x^3]_0^1=x^3\big|_{x=1}-x^3\big|_{x=0}$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000004' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000043', '40000000-0000-4000-8000-000000000004', 'Avalie no limite superior', 'No extremo $1$, obtemos $1^3=1$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000004' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000044', '40000000-0000-4000-8000-000000000004', 'Subtraia o limite inferior', 'No extremo $0$, obtemos $0^3=0$; então $1-0=1$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000004' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000045', '40000000-0000-4000-8000-000000000004', 'Interprete o resultado', 'A constante de integração não aparece em integrais definidas, pois ela se cancela na subtração.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000004' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000051', '40000000-0000-4000-8000-000000000005', 'Reconheça o produto', 'O integrando é $x e^x$, um produto para o qual integração por partes é apropriada.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000005' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000052', '40000000-0000-4000-8000-000000000005', 'Escolha $u$ e $dv$', 'Tome $u=x$ e $dv=e^x\,dx$. Assim, $du=dx$ e $v=e^x$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000005' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000053', '40000000-0000-4000-8000-000000000005', 'Aplique a fórmula', 'Usamos $\int u\,dv=uv-\int v\,du$, obtendo $xe^x-\int e^x\,dx$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000005' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000054', '40000000-0000-4000-8000-000000000005', 'Complete o cálculo', 'Como $\int e^x\,dx=e^x$, a primitiva fica $xe^x-e^x+C=(x-1)e^x+C$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000005' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000055', '40000000-0000-4000-8000-000000000005', 'Confira por derivação', 'A derivada de $(x-1)e^x$ é $e^x+(x-1)e^x=xe^x$.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000005' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000061', '40000000-0000-4000-8000-000000000006', 'Localize os termos dominantes', 'No numerador e no denominador, os termos de maior grau são respectivamente $2n$ e $n$.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000006' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000062', '40000000-0000-4000-8000-000000000006', 'Normalize a fração', 'Divida numerador e denominador por $n$: $(2+1/n)/(1+3/n)$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000006' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000063', '40000000-0000-4000-8000-000000000006', 'Use o comportamento de $1/n$', 'Quando $n$ cresce sem limite, tanto $1/n$ quanto $3/n$ tendem a zero.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000006' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000064', '40000000-0000-4000-8000-000000000006', 'Calcule o limite', 'A expressão tende a $(2+0)/(1+0)=2$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000006' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000065', '40000000-0000-4000-8000-000000000006', 'Elimine distrações', 'Não se divide $2$ por $3$: os coeficientes relevantes são os dos termos de maior grau.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000006' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000071', '40000000-0000-4000-8000-000000000007', 'Reconheça a série', 'A razão entre termos consecutivos é $1/2$, portanto esta também é uma série geométrica.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000007' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000072', '40000000-0000-4000-8000-000000000007', 'Observe o início', 'Como a soma começa em $n=1$, o primeiro termo é $a=1/2$, não $1$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000007' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000073', '40000000-0000-4000-8000-000000000007', 'Verifique a convergência', 'Temos $|r|=1/2<1$, então a soma infinita existe.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000007' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000074', '40000000-0000-4000-8000-000000000007', 'Aplique a fórmula', 'A soma é $a/(1-r)=(1/2)/(1-1/2)=1$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000007' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000075', '40000000-0000-4000-8000-000000000007', 'Faça um teste rápido', 'As somas parciais $1/2$, $3/4$, $7/8$ se aproximam de $1$, confirmando o resultado.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000007' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000081', '40000000-0000-4000-8000-000000000008', 'Escreva a regra', 'Para $\begin{pmatrix}a&b\\c&d\end{pmatrix}$, o determinante é $ad-bc$.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000008' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000082', '40000000-0000-4000-8000-000000000008', 'Associe as entradas', 'Nesta matriz, $a=1$, $b=2$, $c=3$ e $d=1$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000008' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000083', '40000000-0000-4000-8000-000000000008', 'Calcule os produtos', 'Temos $ad=1\cdot1=1$ e $bc=2\cdot3=6$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000008' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000084', '40000000-0000-4000-8000-000000000008', 'Subtraia na ordem certa', 'Logo, $ad-bc=1-6=-5$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000008' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000085', '40000000-0000-4000-8000-000000000008', 'Confira o sinal', 'Inverter a ordem para $bc-ad$ mudaria indevidamente o sinal; a alternativa correta é $-5$.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000008' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000091', '40000000-0000-4000-8000-000000000009', 'Reconheça a estrutura', 'A matriz é diagonal: todos os elementos fora da diagonal principal são zero.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000009' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000092', '40000000-0000-4000-8000-000000000009', 'Use a propriedade', 'Em uma matriz diagonal, cada entrada da diagonal já é um autovalor.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000009' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000093', '40000000-0000-4000-8000-000000000009', 'Leia os valores', 'As entradas diagonais são $2$ e $5$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000009' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000094', '40000000-0000-4000-8000-000000000009', 'Relacione ao polinômio', 'De fato, $\det(A-\lambda I)=(2-\lambda)(5-\lambda)$, cujas raízes são $2$ e $5$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000009' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000095', '40000000-0000-4000-8000-000000000009', 'Conclua', 'Portanto, a alternativa que lista $2$ e $5$ é a correta.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000009' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000101', '40000000-0000-4000-8000-000000000010', 'Escreva a definição', 'O produto escalar soma os produtos das coordenadas correspondentes.', 1 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000010' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000102', '40000000-0000-4000-8000-000000000010', 'Emparelhe as coordenadas', 'Para $u=(1,2,-1)$ e $v=(2,0,3)$, usamos $1\cdot2$, $2\cdot0$ e $(-1)\cdot3$.', 2 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000010' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000103', '40000000-0000-4000-8000-000000000010', 'Calcule cada parcela', 'Os produtos são $2$, $0$ e $-3$.', 3 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000010' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000104', '40000000-0000-4000-8000-000000000010', 'Some os resultados', '$2+0-3=-1$.', 4 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000010' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
insert into public.question_solution_steps (id, question_id, title, content_markdown, sort_order) select '72000000-0000-4000-8000-000000000105', '40000000-0000-4000-8000-000000000010', 'Verifique o procedimento', 'Não se multiplicam todas as coordenadas entre si: há um produto por posição e depois uma soma.', 5 where exists (select 1 from public.questions where id='40000000-0000-4000-8000-000000000010' and publication_status='published') on conflict (question_id, sort_order) do update set title=excluded.title, content_markdown=excluded.content_markdown;
